package main

import (
	"math"
	"strconv"
	"strings"
)

type Kind uint8

const (
	KEmpty Kind = iota
	KNum
	KStr
	KBool
	KErr
	KRef
)

const (
	ErrNull = 1
	ErrDiv0 = 2
	ErrValue = 3
	ErrRef = 4
	ErrName = 5
	ErrNum = 6
	ErrNA = 7
)

var errNames = []string{"", "#NULL!", "#DIV/0!", "#VALUE!", "#REF!", "#NAME?", "#NUM!", "#N/A"}

func errFromString(s string) int {
	for i, n := range errNames {
		if n == s {
			return i
		}
	}
	return ErrValue
}

type Ref struct {
	sheet          int
	r1, c1, r2, c2 int
}

type Val struct {
	k   Kind
	n   float64
	s   string
	ref Ref
}

func numVal(f float64) Val   { return Val{k: KNum, n: f} }
func strVal(s string) Val    { return Val{k: KStr, s: s} }
func boolVal(b bool) Val {
	if b {
		return Val{k: KBool, n: 1}
	}
	return Val{k: KBool, n: 0}
}
func errVal(e int) Val { return Val{k: KErr, n: float64(e)} }

var emptyVal = Val{k: KEmpty}

// ---------- tokenizer ----------

type tokKind uint8

const (
	tNum tokKind = iota
	tStr
	tIdent
	tRef
	tOp
	tLParen
	tRParen
	tComma
	tEOF
)

type token struct {
	k tokKind
	s string
	n float64
}

func isLetter(c byte) bool { return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') }
func isDigit(c byte) bool  { return c >= '0' && c <= '9' }

func tokenize(f string) []token {
	var toks []token
	i := 0
	n := len(f)
	for i < n {
		c := f[i]
		switch {
		case c == ' ' || c == '\n' || c == '\r' || c == '\t':
			i++
		case isDigit(c) || (c == '.' && i+1 < n && isDigit(f[i+1])):
			j := i
			for j < n && (isDigit(f[j]) || f[j] == '.') {
				j++
			}
			if j < n && (f[j] == 'E' || f[j] == 'e') {
				k := j + 1
				if k < n && (f[k] == '+' || f[k] == '-') {
					k++
				}
				if k < n && isDigit(f[k]) {
					for k < n && isDigit(f[k]) {
						k++
					}
					j = k
				}
			}
			v, _ := strconv.ParseFloat(f[i:j], 64)
			toks = append(toks, token{k: tNum, n: v})
			i = j
		case c == '"':
			var b strings.Builder
			j := i + 1
			for j < n {
				if f[j] == '"' {
					if j+1 < n && f[j+1] == '"' {
						b.WriteByte('"')
						j += 2
						continue
					}
					break
				}
				b.WriteByte(f[j])
				j++
			}
			toks = append(toks, token{k: tStr, s: b.String()})
			i = j + 1
		case c == '\'':
			// quoted sheet name
			j := i + 1
			var b strings.Builder
			for j < n {
				if f[j] == '\'' {
					if j+1 < n && f[j+1] == '\'' {
						b.WriteByte('\'')
						j += 2
						continue
					}
					break
				}
				b.WriteByte(f[j])
				j++
			}
			j++ // skip closing quote
			// expect '!'
			if j < n && f[j] == '!' {
				j++
			}
			k := j
			for k < n && (isLetter(f[k]) || isDigit(f[k]) || f[k] == '$' || f[k] == ':') {
				k++
			}
			toks = append(toks, token{k: tRef, s: b.String() + "!" + f[j:k]})
			i = k
		case isLetter(c) || c == '$' || c == '_':
			j := i
			for j < n && (isLetter(f[j]) || isDigit(f[j]) || f[j] == '$' || f[j] == '_' || f[j] == '.') {
				j++
			}
