	} else {
		mm += 9
	}
	doy := (153*mm+2)/5 + int64(d) - 1
	doe := yoe*365 + yoe/4 - yoe/100 + doy
	days := era*146097 + doe - 719468 // days since 1970-01-01
	return days + 25569             // serial: 1899-12-30 = 0
}

func civilFromDays(serial int64) (y, m, d int) {
	z := serial - 25569 + 719468
	var era int64
	if z >= 0 {
		era = z / 146097
	} else {
		era = (z - 146096) / 146097
	}
	doe := z - era*146097
	yoe := (doe - doe/1460 + doe/36524 - doe/146096) / 365
	yy := yoe + era*400
	doy := doe - (365*yoe + yoe/4 - yoe/100)
	mp := (5*doy + 2) / 153
	d = int(doy - (153*mp+2)/5 + 1)
	if mp < 10 {
		m = int(mp + 3)
	} else {
		m = int(mp - 9)
	}
	if m <= 2 {
		yy++
	}
	y = int(yy)
	return
}

func daysInMonth(y, m int) int {
	switch m {
	case 1, 3, 5, 7, 8, 10, 12:
		return 31
	case 4, 6, 9, 11:
		return 30
	}
	if (y%4 == 0 && y%100 != 0) || y%400 == 0 {
		return 29
	}
	return 28
}

func addMonths(serial int64, months int) int64 {
	y, m, d := civilFromDays(serial)
	t := y*12 + (m - 1) + months
	ny := t / 12
	nm := t%12 + 1
	if t < 0 {
		ny = (t - 11) / 12
		nm = t - ny*12 + 1
	}
	dim := daysInMonth(ny, nm)
	if d > dim {
		d = dim
	}
	return daysFromCivil(ny, nm, d)
}

