func fnSWITCH(ctx *Ctx, args []Node) Val {
	x := arg(ctx, args, 0)
	if x.k == KErr {
		return x
	}
	i := 1
	for ; i+1 < len(args); i += 2 {
		c := arg(ctx, args, i)
		if c.k == KErr {
			return c
		}
		if compareVals(x, c) == 0 && ((x.k == KStr) == (c.k == KStr)) {
			return arg(ctx, args, i+1)
		}
	}
	if i < len(args) {
		return arg(ctx, args, i)
	}
	return errVal(ErrNA)
}

func logicalCollect(ctx *Ctx, args []Node) ([]bool, int) {
	var out []bool
	var errc int
	for i := range args {
		if args[i] == nil {
			continue
		}
		v := eval(ctx, args[i])
		if v.k == KRef {
			if v.ref.r1 == v.ref.r2 && v.ref.c1 == v.ref.c2 {
				cv := deref(ctx, v)
				if cv.k == KErr {
					return nil, int(cv.n)
				}
				if cv.k == KNum || cv.k == KBool {
					out = append(out, cv.n != 0)
				}
				continue
			}
			forRange(ctx, v.ref, func(cv Val) bool {
				if cv.k == KErr {
					errc = int(cv.n)
					return false
				}
				if cv.k == KNum || cv.k == KBool {
					out = append(out, cv.n != 0)
				}
				return true
			})
			if errc != 0 {
				return nil, errc
			}
			continue
		}
		b, e := toBool(v)
		if e != 0 {
			return nil, e
		}
		out = append(out, b)
	}
	return out, 0
}

func fnAND(ctx *Ctx, args []Node) Val {
	bs, e := logicalCollect(ctx, args)
	if e != 0 {
		return errVal(e)
	}
	if len(bs) == 0 {
		return errVal(ErrValue)
	}
	for _, b := range bs {
		if !b {
			return boolVal(false)
		}
	}
	return boolVal(true)
}

func fnOR(ctx *Ctx, args []Node) Val {
