func fnPROPER(ctx *Ctx, args []Node) Val {
	s, e := argStr(ctx, args, 0)
	if e != 0 {
		return errVal(e)
	}
	var b strings.Builder
	prevLetter := false
	for _, r := range s {
		if unicode.IsLetter(r) {
			if prevLetter {
				b.WriteRune(unicode.ToLower(r))
			} else {
				b.WriteRune(unicode.ToUpper(r))
			}
			prevLetter = true
		} else {
			b.WriteRune(r)
			prevLetter = false
		}
	}
	return strVal(b.String())
}

