func concatAll(ctx *Ctx, args []Node, skipEmpty bool, delim string) Val {
	var parts []string
	var errc int
	add := func(v Val) bool {
		if v.k == KErr {
			errc = int(v.n)
			return false
		}
		s, _ := toStr(v)
		if skipEmpty && s == "" {
			return true
		}
		parts = append(parts, s)
		return true
	}
	for i := range args {
		if args[i] == nil {
			continue
		}
		v := eval(ctx, args[i])
		if v.k == KRef {
			forRange(ctx, v.ref, add)
		} else {
			add(v)
		}
		if errc != 0 {
			return errVal(errc)
		}
	}
	return strVal(strings.Join(parts, delim))
}

