	if len(args) > 3 && args[3] != nil {
		n, e := argNum(ctx, args, 3)
		if e != 0 {
			return errVal(e)
		}
		k := int(n)
		if k < 1 {
			return errVal(ErrValue)
		}
		idx := 0
		pos := 0
		for {
			i := strings.Index(s[pos:], old)
			if i < 0 {
				return strVal(s)
			}
			idx++
			if idx == k {
				return strVal(s[:pos+i] + nw + s[pos+i+len(old):])
			}
			pos += i + len(old)
		}
	}
	return strVal(strings.ReplaceAll(s, old, nw))
}

