new='''	// parse all formulas and classify independence in parallel
	type pj struct {
		cell  *Cell
		si    int
		r, c  int
		indep bool
	}
	var all []pj
	for si, sh := range book.sheets {
		for c := range sh.cols {
			for r, cell := range sh.cols[c] {
				if cell != nil && cell.hasF {
					all = append(all, pj{cell: cell, si: si, r: r, c: c})
				}
			}
		}
	}
	{
		var wg sync.WaitGroup
		chunk := (len(all) + nCPU - 1) / nCPU
		for w := 0; w < nCPU; w++ {
			lo, hi := w*chunk, (w+1)*chunk
			if hi > len(all) {
				hi = len(all)
			}
			if lo >= hi {
				continue
			}
			wg.Add(1)
			go func(part []pj) {
				defer wg.Done()
				var refs []Ref
				for pi := range part {
					p := &part[pi]
					p.cell.ast = parseFormula(p.cell.formula, book, p.si)
					refs = refs[:0]
					collectRefs(p.cell.ast, &refs)
					indep := true
					for _, rf := range refs {
						if hasF[rf.sheet] == 0 {
							continue
						}
						n := (rf.r2 - rf.r1 + 1) * (rf.c2 - rf.c1 + 1)
						if n > 4096 {
							indep = false
							break
						}
						tsh := book.sheets[rf.sheet]
						for cc := rf.c1; cc <= rf.c2 && indep; cc++ {
							for rr := rf.r1; rr <= rf.r2; rr++ {
								t := tsh.get(rr, cc)
								if t != nil && t.hasF {
									indep = false
									break
								}
							}
						}
						if !indep {
							break
						}
					}
					p.indep = indep
				}
			}(all[lo:hi])
		}
		wg.Wait()
	}
	for _, p := range all {
		if p.indep {
			jobs = append(jobs, job{p.si, p.r, p.c})
		}
	}
'''
m=m[:old_start]+new+m[old_end:]
open('main.go','w').write(m)
EOF
